// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testRegression_property() public {
        address attacker = address(0xdead);
        vm.deal(address(c), 1 ether);
        vm.deal(attacker, 0 ether);
        vm.prank(attacker);
        bool ok;
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
